def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            colors = set(grid[y][x] for y, x in cells)
            boxes = {}
            for color in colors:
                pts = [(y, x) for y, x in cells if grid[y][x] == color]
                boxes[color] = (
                    min(y for y, x in pts), max(y for y, x in pts),
                    min(x for y, x in pts), max(x for y, x in pts)
                )
            ordered = sorted(colors, key=lambda color: (
                (boxes[color][1] - boxes[color][0] + 1) *
                (boxes[color][3] - boxes[color][2] + 1)
            ), reverse=True)
            remap = dict(zip(ordered, reversed(ordered)))
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
